(()=>{
const colors=['#cc744d','#658bd1','#a27bc5','#699b74'];const key='matclub-graphs-v1';let rows=[{text:'x^2',visible:true},{text:'2x + 1',visible:true}],view={x:0,y:0,scale:45};try{const data=JSON.parse(localStorage.getItem(key));if(Array.isArray(data?.rows)&&data.rows.length)rows=data.rows.slice(0,4).map(r=>({text:String(r.text||'').slice(0,200),visible:r.visible!==false}));if(Number.isFinite(data?.view?.x)&&Math.abs(data.view.x)<1e7&&Number.isFinite(data.view.y)&&Math.abs(data.view.y)<1e7&&data.view.scale>=.00001&&data.view.scale<=100000)view=data.view}catch{}
let compiled=[],width=800,height=520,drag=null,frame=0;const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(key,JSON.stringify({rows,view}))}catch{$('#graphStatus').textContent='Графики построены, но браузер не разрешил сохранить их.'}}
function compile(){compiled=rows.map(r=>{try{return {fn:MathFormula.compile(r.text)}}catch(e){return {error:e.message}}});for(let i=0;i<rows.length;i++){const error=$(`[data-formula-error="${i}"]`);if(error){error.textContent=compiled[i].error||'';$(`[data-formula="${i}"]`).setAttribute('aria-invalid',String(!!compiled[i].error))}}}
function fields(){ $('#formulaRows').innerHTML=rows.map((r,i)=>`<div class="formula-row" style="--curve:${colors[i]}"><div class="formula-entry"><input type="checkbox" data-visible="${i}" ${r.visible?'checked':''} aria-label="Показать график ${i+1}"><label for="formula-${i}">y =</label><input id="formula-${i}" data-formula="${i}" value="${safe(r.text)}" maxlength="200" spellcheck="false" autocomplete="off" aria-label="Формула ${i+1}" aria-describedby="formula-error-${i}"><button data-remove-formula="${i}" aria-label="Удалить формулу ${i+1}" ${rows.length===1?'disabled':''}>×</button></div><p id="formula-error-${i}" data-formula-error="${i}" class="formula-error" role="status"></p></div>`).join('');$('#addFormula').disabled=rows.length>=4;compile()}
const coord=(px,py)=>({x:view.x+(px-width/2)/view.scale,y:view.y-(py-height/2)/view.scale});const px=x=>width/2+(x-view.x)*view.scale,py=y=>height/2-(y-view.y)*view.scale;
function num(n){return Math.abs(n)<1e-10?'0':Math.abs(n)>=1e5||Math.abs(n)<.001?Number(n.toPrecision(3)).toExponential():Number(n.toPrecision(5)).toString()}
function curve(fn){let d='',previous=null;const evaluate=x=>{try{return fn(x)}catch{return NaN}};for(let sx=0;sx<=width;sx+=1.5){const x=coord(sx,0).x,y=evaluate(x),sy=py(y);if(!Number.isFinite(sy)||Math.abs(sy)>height*20){previous=null;continue}if(previous){const mid=py(evaluate((previous.x+x)/2));if(!Number.isFinite(mid)||Math.abs(sy-previous.sy)>height*.9||Math.abs(mid-(sy+previous.sy)/2)>height*.25){previous=null}}d+=(previous?'L':'M')+sx.toFixed(1)+','+Math.max(-height*20,Math.min(height*20,sy)).toFixed(1);previous={x,sy}}return d}
function draw(){if($('#graphSection').hidden)return;const rect=$('#plotArea').getBoundingClientRect();width=Math.max(280,rect.width||800);height=window.innerWidth<600?380:520;const x0=px(0),y0=py(0),span=75/view.scale,base=10**Math.floor(Math.log10(span)),m=span/base,step=(m>5?10:m>2?5:m>1?2:1)*base;let grid='',labels='';const lo=coord(0,height),hi=coord(width,0);for(let x=Math.ceil(lo.x/step)*step,count=0;x<=hi.x&&count<100;x+=step,count++){const a=px(x);grid+=`<path d="M${a} 0V${height}"/>`;labels+=`<text x="${a+5}" y="${Math.max(15,Math.min(height-8,y0+17))}">${num(x)}</text>`}for(let y=Math.ceil(lo.y/step)*step,count=0;y<=hi.y&&count<100;y+=step,count++){const a=py(y);grid+=`<path d="M0 ${a}H${width}"/>`;if(Math.abs(y)>step*.001)labels+=`<text x="${Math.max(5,Math.min(width-60,x0+7))}" y="${a-5}">${num(y)}</text>`}let paths='';compiled.forEach((c,i)=>{if(c.fn&&rows[i].visible)paths+=`<path d="${curve(c.fn)}" fill="none" stroke="${colors[i]}" stroke-width="2.5" vector-effect="non-scaling-stroke"/>`});$('#plotSvg').setAttribute('viewBox',`0 0 ${width} ${height}`);$('#plotSvg').innerHTML=`<defs><clipPath id="plotClip"><rect width="${width}" height="${height}"/></clipPath></defs><g class="plot-grid">${grid}</g><g class="plot-axes"><path d="M${x0} 0V${height}M0 ${y0}H${width}"/></g><g class="plot-labels">${labels}</g><g clip-path="url(#plotClip)">${paths}</g>`;$('#graphRange').textContent=`x: ${num(lo.x)} … ${num(hi.x)} · y: ${num(lo.y)} … ${num(hi.y)}`;$('#graphStatus').textContent=compiled.some(c=>c.error)?'В одной из формул есть ошибка. Остальные графики показаны.':'Графики построены. Перетаскивай плоскость или меняй масштаб.';table()}
function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(draw)}function table(){const n=Number($('#graphSampleX').value);if(!Number.isFinite(n)){ $('#graphValues').textContent='Введи конечное число x.';return}$('#graphValues').innerHTML=compiled.map((c,i)=>{let y;try{y=c.fn?.(n)}catch{}return `<div><span style="color:${colors[i]}">f${i+1}(${safe(num(n))})</span><b>${Number.isFinite(y)?safe(num(y)):'не определено'}</b></div>`}).join('')}
function zoom(factor,anchorX=width/2,anchorY=height/2){const before=coord(anchorX,anchorY);view.scale=Math.max(.00001,Math.min(100000,view.scale*factor));view.x=before.x-(anchorX-width/2)/view.scale;view.y=before.y+(anchorY-height/2)/view.scale;schedule();save()}
let timer;document.addEventListener('input',e=>{if(e.target.dataset.formula!==undefined){rows[+e.target.dataset.formula].text=e.target.value;clearTimeout(timer);timer=setTimeout(()=>{compile();draw();save()},180)}if(e.target.id==='graphSampleX')table()});document.addEventListener('change',e=>{if(e.target.dataset.visible!==undefined){rows[+e.target.dataset.visible].visible=e.target.checked;draw();save()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.removeFormula!==undefined&&rows.length>1){rows.splice(+b.dataset.removeFormula,1);fields();draw();save()}if(b.id==='addFormula'&&rows.length<4){rows.push({text:'sin(x)',visible:true});fields();draw();save();$(`[data-formula="${rows.length-1}"]`).focus()}if(b.dataset.graphExample){rows=[{text:b.dataset.graphExample,visible:true}];fields();draw();save()}if(b.id==='zoomIn')zoom(1.3);if(b.id==='zoomOut')zoom(1/1.3);if(b.id==='resetGraph'){view={x:0,y:0,scale:45};draw();save()}if(b.id==='downloadGraph'){const svg=$('#plotSvg').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.plot-grid{fill:none;stroke:#e1e6db;stroke-width:1}.plot-axes{fill:none;stroke:#718069;stroke-width:1.3}.plot-labels{fill:#607057;font:11px sans-serif}';svg.prepend(style);const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','100%');bg.setAttribute('height','100%');bg.setAttribute('fill','#fffefa');svg.insertBefore(bg,style.nextSibling);const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='matclub-graph.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
const area=$('#plotArea');area.addEventListener('wheel',e=>{e.preventDefault();const r=area.getBoundingClientRect();zoom(Math.exp(-Math.max(-100,Math.min(100,e.deltaY))*.003),e.clientX-r.left,e.clientY-r.top)},{passive:false});area.addEventListener('pointerdown',e=>{if(e.button!==0)return;area.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,cx:view.x,cy:view.y};area.classList.add('dragging')});area.addEventListener('pointermove',e=>{const r=area.getBoundingClientRect(),c=coord(e.clientX-r.left,e.clientY-r.top);$('#graphCursor').textContent=`x ${num(c.x)} · y ${num(c.y)}`;if(drag&&drag.id===e.pointerId){view.x=Math.max(-1e7,Math.min(1e7,drag.cx-(e.clientX-drag.x)/view.scale));view.y=Math.max(-1e7,Math.min(1e7,drag.cy+(e.clientY-drag.y)/view.scale));schedule()}});function end(){if(drag)save();drag=null;area.classList.remove('dragging')}area.addEventListener('pointerup',end);area.addEventListener('pointercancel',end);area.addEventListener('lostpointercapture',end);area.addEventListener('keydown',e=>{const move=30/view.scale;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')view.x-=move;if(e.key==='ArrowRight')view.x+=move;if(e.key==='ArrowUp')view.y+=move;if(e.key==='ArrowDown')view.y-=move;if(e.key==='+'||e.key==='=')zoom(1.3);if(e.key==='-')zoom(1/1.3);if(e.key==='0')view={x:0,y:0,scale:45};draw();save()}});if(typeof ResizeObserver!=='undefined')new ResizeObserver(schedule).observe(area);window.addEventListener('resize',schedule);fields();window.matclubPlotter={refresh(){compile();draw()},curve,zoom,get state(){return {rows,view}},draw};
})();
